use vstd::prelude::*;

verus! {
    /// Given n items, k of which are selected, returns a length‐2
    /// vector [x_min, x_max] of how many *unselected* items can be “good.”
    ///
    /// - If k == 0 or k == n, no unselected item can be good, so we return [0,0].
    /// - Otherwise, at least one unselected item is good, and at most
    ///   min(unselected, 2*k) can be good.
    fn solve(n: i8, k: i8) -> (res: Vec<i8>)
        requires
            // we only consider 0 ≤ k ≤ n
            0 <= n,
            0 <= k,
            k <= n,
        ensures
            // must always return exactly two entries
            res.len() == 2,
            // if nothing or everything is selected ⇒ answer is [0,0]
            if k == 0 || k == n {
                res[0] == 0 && res[1] == 0
            } else {
                // otherwise exactly as in the implementation
                let unselected = n - k;
                res[0] == 1 &&
                // we use the same saturating_mul + min logic
                res[1] == std::cmp::min(unselected, k.saturating_mul(2))
            },
    {
        // (implementation unchanged)

        // If nothing is selected or everything is selected, there
        // cannot be any "good" unselected items.
        if k == 0 || k == n {
            return vec![0, 0];
        }

        // Otherwise, at least one must be good, and at most
        // min(unselected, 2*k) can be good.
        let unselected = n - k;
        let x_min = 1;
        // saturating_mul never overflows; if 2*k > i8::MAX it becomes i8::MAX,
        // and we'll still take the min against `unselected`.
        let x_max = k.saturating_mul(2).min(unselected);

        vec![x_min, x_max]
    }
}

